head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_tabsel_table_10();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil17101.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_tabsel_table_10
 * @description 초기화 — tabsel table 10
 * @returns {void}
 * @hidden N
 */
scwin.init_tabsel_table_10 = function () {
    const tc = $c.util.getComponent('table_10');
    if (tc && tc.setSelectedTabIndex && tc.getSelectedTabIndex() !== 1) { tc.setSelectedTabIndex(1); }
};

// [A] 초기 목록 미해결 — 진입 키 qna 를 쓰는 tx 가 2개다(tx_fn_Search, tx_fn_searchQnaResult)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_table_10_ontabclick
 * @description tab_table_10 탭 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab_table_10_ontabclick = async function(e){ try { const i = (e && e.selectedTabIndex !== undefined) ? e.selectedTabIndex : (typeof e === 'number' ? e : (($c.util.getComponent('table_10') || {}).getSelectedTabIndex ? $c.util.getComponent('table_10').getSelectedTabIndex() : 0)); const fns = [async function(){ await scwin.register() }, async function(){ await scwin.searchQnaResult() }]; if (i !== 1 && fns[i]) fns[i](); } catch (err) { await $c.exception.handleError(err, { notify: 'none', context: 'tab_table_10' }); } };

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17101.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_qnaResultList_oncellclick
 * @description grd_qnaResultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_qnaResultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_qnaResultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_qnaResultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchDetail(r["quesID"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_qnaResultList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_50_onclick
 * @description krxpage_pagenavigator_50 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_50_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_registerReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_50.page' }); } await scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_registerReq",
        target: "dlt_qnaResultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_SearchReq",
        target: "dlt_qnaResultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchQnaResult
 * @description search Qna Result 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchQnaResult = async function () {
    const sbmOptions = {
        id: "tx_fn_searchQnaResult",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_searchQnaResultReq",
        target: "dlt_qnaResultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchDetail",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_SearchDetailReq",
        target: "dlt_qnaResultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = (document.qnaResultForm || { elements: [] });
    $c.util.getComponent('dma_registerReq').set('method', 'searchQnaApply');
    frm.action = 'qna.do';
    const nr = await scwin.tx_fn_register();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17100/jldfil17100.xml", { "method": 'searchQnaApply' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.qnaResultForm || { elements: [] });
    $c.util.getComponent('dma_registerReq').set('method', 'searchQnaResult');
    frm.action = 'qna.do';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name searchQnaResult
 * @description search Qna Result 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchQnaResult = async function () {
    const frm = (document.qnaResultForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_registerReq').set('method', 'searchQnaResult');
    await scwin.tx_fn_searchQnaResult();
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (contnId) {
    const frm = (document.qnaResultForm || { elements: [] });
    $c.util.getComponent('dma_registerReq').set('method', 'searchQnaResultDetail');
    $c.util.getComponent('dma_registerReq').set('contnId', contnId);
    frm.action = 'qna.do';
    const nr = await scwin.tx_fn_SearchDetail();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17102/jldfil17102.xml", { "method": 'searchQnaResultDetail', "contnId": contnId });
    }
};
